import { IBaseHiking } from '../../Hiking/@types/hikingList.types';

export enum ObstacleCategory {
  CategoryNo = 'no',
  Category1a = '1a',
  Category1b = '1b',
  Category2a = '2a',
  Category2b = '2b',
  Category3a = '3a',
  Category3b = '3b',
  Category4a = '4a',
  Category4b = '4b',
  Category5a = '5a',
  Category5b = '5b',
  Category6a = '6a',
  Category6b = '6b',
}

export enum ObstacleType {
  Pass = 'pass',
  Peak = 'peak',
  Poi = 'poi',
}

export interface IBaseObstacle {
  id: number;
  name: string;
  type: ObstacleType;
  category: ObstacleCategory;
}

export interface IObstacle extends IBaseObstacle {
  description: string;
  coordinates: [number, number];
  altitude: number;
  link: string;
  comment: string;

  created: {
    date: Date;
    id: number;
    name: string;
  };

  updated: null | {
    date: Date;
    id: number;
    name: string;
  };

  region: null | {
    id: number;
    name: string;
  };
}

export interface IObstacleForUser extends IObstacle {
  id_hiking_obstacle: number;
  date_in: Date;
  date_out: Date;
  hiking: IBaseHiking;
}
